def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            if float(opp.get('budget', 0)) >= DAILY_SALARY * 4:
                rich_opp += 1
            if int(opp.get('hp', 0)) <= 2 or int(opp.get('no_water_days', 0)) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))

    if not alive_opps:
        return float(min(budget, 18.0))

    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    max_prev = max(prev_bids) if prev_bids else 0.0

    supply_pressure = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    supply_pressure = max(0.0, min(1.0, supply_pressure))

    risk = 0.0
    if hp <= 1:
        risk += 1.0
    elif hp <= 2:
        risk += 0.7
    elif hp <= 4:
        risk += 0.35

    if no_water >= 2:
        risk += 0.9
    elif no_water >= 1:
        risk += 0.45

    risk += supply_pressure * 0.45
    risk += min(0.35, urgent_opp * 0.08)

    if hp <= 2 or no_water >= 2:
        target = max(62.0, max_prev + 3.0, avg_prev + 6.0)
    elif supply >= 22 and hp >= 4 and no_water == 0:
        target = 16.0 + rich_opp * 2.0
    elif supply >= 20 and max_prev > 95 and hp >= 4:
        target = 22.0
    else:
        base = 20.0 + supply_pressure * 18.0 + min(12.0, avg_prev * 0.12)
        if max_prev >= 110:
            base -= 6.0
        elif max_prev >= 80:
            base += 4.0
        base += rich_opp * 1.5
        target = base + risk * 22.0

    if day >= 8:
        target += 6.0 * risk
    if day == 10:
        target += 8.0

    min_safe = 0.0
    days_left = max(0, 10 - day)
    if days_left >= 2 and hp >= 3 and no_water == 0:
        min_safe = 0.0

    bid = min(budget - min_safe, target)
    bid = max(0.0, bid)

    if hp >= 5 and no_water == 0 and supply >= 23 and max_prev >= 100:
        bid = min(bid, 18.0)

    if hp <= 1:
        bid = min(budget, max(bid, 68.0))

    return float(round(max(0.0, min(budget, bid)), 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # Alive opponents and their yesterday bids
    alive_opponents = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    if not alive_opponents:
        # If no opponents alive, spend to secure requirement
        return int(min(my_status['budget'], DAILY_SALARY * 0.5))

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Pressure logic: Cindy/Alex/Eric were around ~100; bid just above when supply is tight.
    # Supply tightness: fewer multiples of WATER_REQ implies higher scarcity pressure.
    # Avoid float indices by not indexing lists.
    scarcity_ratio = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        scarcity_ratio = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY + 1e-9)

    # Base bid target
    # If yesterday's max bid indicates strong competition, increase bid slightly.
    if highest_prev_bid >= 0.85 * DAILY_SALARY:
        # When competition was high, only overbid if my HP is at risk or supply is tight.
        if my_status['hp'] <= 3 or scarcity_ratio >= 0.5:
            target = highest_prev_bid + 3.0
        else:
            target = max(DAILY_SALARY * 0.55, highest_prev_bid - 5.0)
    else:
        # Moderate competition: bid enough to not lose consistently, but conserve budget.
        if my_status['hp'] <= 2:
            target = DAILY_SALARY * 0.85
        else:
            target = DAILY_SALARY * (0.45 + 0.25 * scarcity_ratio)

    # Ensure we don't bid above budget; also avoid bidding too low when supply is very tight.
    budget = float(my_status.get('budget', 0.0))
    if budget <= 0:
        return 0

    # Minimum effective bid: if supply is near MIN_SUPPLY, slightly raise to secure water.
    min_effective = DAILY_SALARY * (0.35 + 0.25 * scarcity_ratio)

    final_bid = min(budget, max(target, min_effective if my_status['hp'] > 0 else DAILY_SALARY * 0.9))

    # If we've already had many no-water days, increase aggressiveness.
    no_water_days = int(my_status.get('no_water_days', 0) or 0)
    if no_water_days >= 2:
        final_bid = min(budget, final_bid * 1.15)

    # Return integer bid
    return int(final_bid)
